using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.DTOs;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.CustomerDeliveries;public class EditModel(ApplicationDbContext db,ITransactionService transactions,IPermissionService permissions):PageModel
{[BindProperty]public CustomerDeliveryForm Item{get;set;}=null!;public SelectList Customers{get;private set;}=null!;public IReadOnlyList<PolicyOption> Policies{get;private set;}=[];public async Task<IActionResult> OnGetAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.CustomerDeliveries,PermissionAction.Update))return Forbid();var x=await db.CustomerDeliveries.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();Item=new(){Id=x.Id,CustomerId=x.CustomerId,SupplierReceiptId=x.SupplierReceiptId,Date=x.Date,UnitPrice=x.UnitPrice,TaxPercent=x.TaxPercent,Details=x.Details};await Load();return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.CustomerDeliveries,PermissionAction.Update))return Forbid();if(ModelState.IsValid)try{await transactions.UpdateCustomerDeliveryAsync(Item.Id,new(Item.CustomerId,Item.SupplierReceiptId,Item.Date,Item.UnitPrice,Item.TaxPercent,Item.Details));TempData["Message"]="تم تعديل حركة التوريد";return RedirectToPage("Index");}catch(InvalidOperationException e){ModelState.AddModelError(string.Empty,e.Message);}await Load();return Page();}private async Task Load(){Customers=new(await db.Customers.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");Policies=await transactions.GetUnassignedPoliciesAsync(Item.Id);}}
